SELECT jsonb_build_object('data',(SELECT jsonb_agg(x ORDER BY name) FROM (SELECT 'transactions' name,count(*) n,md5(coalesce(string_agg(to_jsonb(t)::text,E'
' ORDER BY to_jsonb(t)::text),'')) h FROM public.transactions t UNION ALL SELECT 'event_forecasts' name,count(*) n,md5(coalesce(string_agg(to_jsonb(t)::text,E'
' ORDER BY to_jsonb(t)::text),'')) h FROM public.event_forecasts t UNION ALL SELECT 'financial_accounts' name,count(*) n,md5(coalesce(string_agg(to_jsonb(t)::text,E'
' ORDER BY to_jsonb(t)::text),'')) h FROM public.financial_accounts t UNION ALL SELECT 'transaction_payments' name,count(*) n,md5(coalesce(string_agg(to_jsonb(t)::text,E'
' ORDER BY to_jsonb(t)::text),'')) h FROM public.transaction_payments t UNION ALL SELECT 'reimbursement_notes' name,count(*) n,md5(coalesce(string_agg(to_jsonb(t)::text,E'
' ORDER BY to_jsonb(t)::text),'')) h FROM public.reimbursement_notes t UNION ALL SELECT 'reimbursement_note_items' name,count(*) n,md5(coalesce(string_agg(to_jsonb(t)::text,E'
' ORDER BY to_jsonb(t)::text),'')) h FROM public.reimbursement_note_items t UNION ALL SELECT 'payment_lists' name,count(*) n,md5(coalesce(string_agg(to_jsonb(t)::text,E'
' ORDER BY to_jsonb(t)::text),'')) h FROM public.payment_lists t UNION ALL SELECT 'data_entry_sessions' name,count(*) n,md5(coalesce(string_agg(to_jsonb(t)::text,E'
' ORDER BY to_jsonb(t)::text),'')) h FROM public.data_entry_sessions t WHERE owner_id IS DISTINCT FROM '00000000-0000-0000-0000-000000000000'::uuid UNION ALL SELECT 'data_entry_documents' name,count(*) n,md5(coalesce(string_agg(to_jsonb(t)::text,E'
' ORDER BY to_jsonb(t)::text),'')) h FROM public.data_entry_documents t WHERE session_id NOT IN (SELECT id FROM public.data_entry_sessions WHERE owner_id='00000000-0000-0000-0000-000000000000'::uuid) UNION ALL SELECT 'data_entry_previews' name,count(*) n,md5(coalesce(string_agg(to_jsonb(t)::text,E'
' ORDER BY to_jsonb(t)::text),'')) h FROM public.data_entry_previews t WHERE session_id NOT IN (SELECT id FROM public.data_entry_sessions WHERE owner_id='00000000-0000-0000-0000-000000000000'::uuid) UNION ALL SELECT 'data_entry_results' name,count(*) n,md5(coalesce(string_agg(to_jsonb(t)::text,E'
' ORDER BY to_jsonb(t)::text),'')) h FROM public.data_entry_results t WHERE approved_by IS DISTINCT FROM '00000000-0000-0000-0000-000000000000'::uuid UNION ALL SELECT 'standalone_invoices' name,count(*) n,md5(coalesce(string_agg(to_jsonb(t)::text,E'
' ORDER BY to_jsonb(t)::text),'')) h FROM public.standalone_invoices t WHERE created_by IS DISTINCT FROM '00000000-0000-0000-0000-000000000000'::uuid UNION ALL SELECT 'standalone_attempts_333' name,count(*) n,md5(coalesce(string_agg(to_jsonb(t)::text,E'
' ORDER BY to_jsonb(t)::text),'')) h FROM public.standalone_attempts_333 t WHERE principal IS DISTINCT FROM '00000000-0000-0000-0000-000000000000' UNION ALL SELECT 'standalone_attempt_audit_333' name,count(*) n,md5(coalesce(string_agg(to_jsonb(t)::text,E'
' ORDER BY to_jsonb(t)::text),'')) h FROM public.standalone_attempt_audit_333 t WHERE attempt_id NOT IN (SELECT id FROM public.standalone_attempts_333 WHERE principal='00000000-0000-0000-0000-000000000000') UNION ALL SELECT 'data_entry_storage_receipts' name,count(*) n,md5(coalesce(string_agg(to_jsonb(t)::text,E'
' ORDER BY to_jsonb(t)::text),'')) h FROM public.data_entry_storage_receipts t WHERE path NOT IN (SELECT path FROM public.data_entry_documents WHERE session_id IN (SELECT id FROM public.data_entry_sessions WHERE owner_id='00000000-0000-0000-0000-000000000000'::uuid)) AND path NOT IN (SELECT storage_path FROM public.standalone_invoices WHERE created_by='00000000-0000-0000-0000-000000000000'::uuid)) x),'config',(SELECT jsonb_agg(x ORDER BY signature) FROM (SELECT oid::regprocedure::text signature,md5(prosrc) source,proacl::text,proconfig,proowner FROM pg_proc WHERE pronamespace='public'::regnamespace AND (proname LIKE 'data_entry%' OR proname IN ('standalone_attempt_gate_333','standalone_attempts_333_internal'))) x),'core_open',(SELECT count(*) FROM public.data_entry_settings WHERE preparation_validated OR execute_validated),'attempt_open',(SELECT count(*) FROM public.standalone_attempt_settings_333 WHERE enabled),'allowlist_count',(SELECT count(*) FROM public.data_entry_pilot8_allowlist)) baseline